import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { getBook, getBooks } from '@/lib/wordpress';

type Props = { params: Promise<{ slug: string }> };

// Build every book page ahead of time; new books are built on first visit.
export async function generateStaticParams() {
  const books = await getBooks();
  return books.map((book) => ({ slug: book.slug }));
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const book = await getBook((await params).slug);
  if (!book) return {};
  const cover = book.acf.cover_image || null;
  return {
    title: book.title.rendered,
    description: book.acf.subtitle,
    openGraph: cover ? { images: [{ url: cover.url, width: cover.width, height: cover.height, alt: cover.alt }] } : undefined,
  };
}

export default async function BookPage({ params }: Props) {
  const book = await getBook((await params).slug);
  if (!book) notFound();

  const f = book.acf;
  const cover = f.cover_image || null;

  return (
    <article>
      {cover && <img src={cover.url} alt={cover.alt} width={240} style={{ height: 'auto' }} />}
      <h1 dangerouslySetInnerHTML={{ __html: book.title.rendered }} />
      {f.subtitle && <p><em>{f.subtitle}</em></p>}
      <p>
        {f.book_author}
        {f.pages ? ` · ${Number(f.pages)} pages` : ''}
      </p>
      {/* The post body, written in the WordPress editor. */}
      <div dangerouslySetInnerHTML={{ __html: book.content.rendered }} />
      {f.buy_url && <p><a href={f.buy_url}>Buy this book</a></p>}
    </article>
  );
}

import Link from 'next/link';
import { getBooks, getGenres } from '@/lib/wordpress';

export const metadata = { title: 'All books' };

export default async function BooksPage() {
  // Both requests run at the same time.
  const [books, genres] = await Promise.all([getBooks(), getGenres()]);
  const genreName = new Map(genres.map((g) => [g.id, g.name]));

  return (
    <main>
      <h1>Books</h1>
      <ul style={{ listStyle: 'none', padding: 0, display: 'grid', gap: 32, gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))' }}>
        {books.map((book) => {
          const f = book.acf;
          const cover = f.cover_image || null;
          return (
            <li key={book.id}>
              <Link href={`/books/${book.slug}`} style={{ color: 'inherit', textDecoration: 'none' }}>
                {cover && <img src={cover.url} alt="" width={cover.width} height={cover.height} style={{ width: '100%', height: 'auto', borderRadius: 6 }} />}
                <h2 style={{ margin: '12px 0 4px', fontSize: 20 }} dangerouslySetInnerHTML={{ __html: book.title.rendered }} />
              </Link>
              {f.subtitle && <p style={{ margin: 0 }}>{f.subtitle}</p>}
              <p style={{ margin: '4px 0 0', color: '#666', fontSize: 14 }}>
                {f.book_author}
                {f.pages ? ` · ${Number(f.pages)} pages` : ''}
                {book.genre.length > 0 && ` · ${book.genre.map((id) => genreName.get(id)).join(', ')}`}
              </p>
            </li>
          );
        })}
      </ul>
    </main>
  );
}

import type { Metadata } from 'next';
import type { ReactNode } from 'react';

export const metadata: Metadata = {
  title: { default: 'Books', template: '%s · Books' },
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body style={{ fontFamily: 'system-ui, sans-serif', maxWidth: 880, margin: '0 auto', padding: 24 }}>
        {children}
      </body>
    </html>
  );
}

// Every request to WordPress goes through this file, so the rest of the app never
// builds a REST URL by hand.

const WP_URL = process.env.WP_URL;

if (!WP_URL) {
  throw new Error('Set WP_URL in .env.local, e.g. WP_URL=https://your-site.com');
}

// An ACF Image field with Return Format "Image Array", as sent with acf_format=standard.
export type AcfImage = {
  id: number;
  url: string;
  alt: string;
  width: number;
  height: number;
  sizes: Record<string, string | number>;
};

export type Book = {
  id: number;
  slug: string;
  title: { rendered: string };
  excerpt: { rendered: string };
  content: { rendered: string };
  genre: number[];
  // Filled by the "Book Details" ACF field group (Show in REST API on).
  acf: {
    subtitle?: string;
    book_author?: string;
    // ACF sends numbers as strings when acf_format=standard: convert with Number().
    pages?: string | number;
    cover_image?: AcfImage | false;
    buy_url?: string;
  };
};

export type Genre = { id: number; name: string; slug: string };

// Ask only for what the pages use. acf_format=standard makes ACF return each field
// in its Return Format: the cover as an object with its URL, size and alt text.
const BOOK_QUERY = '_fields=id,slug,title,excerpt,content,genre,acf&acf_format=standard';

async function wp<T>(path: string): Promise<T> {
  const res = await fetch(`${WP_URL}/wp-json${path}`, {
    // Re-fetch at most every 5 minutes (incremental static regeneration).
    next: { revalidate: 300 },
  });
  if (!res.ok) {
    throw new Error(`WordPress returned ${res.status} for ${path}`);
  }
  return res.json() as Promise<T>;
}

export function getBooks() {
  return wp<Book[]>(`/wp/v2/book?${BOOK_QUERY}&per_page=100`);
}

export async function getBook(slug: string) {
  const books = await wp<Book[]>(`/wp/v2/book?slug=${encodeURIComponent(slug)}&${BOOK_QUERY}`);
  return books[0] ?? null;
}

export function getGenres() {
  return wp<Genre[]>('/wp/v2/genre?_fields=id,name,slug&per_page=100');
}
